(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x * 0.02 + t * 0.3) * 15 + Math.cos(y * 0.015 - t * 0.2) * 10;
  const w1y = Math.cos(y * 0.02 - t * 0.25) * 15 + Math.sin(x * 0.018 + t * 0.35) * 10;
  const mx = x + w1x, my = y + w1y;
  const w2x = Math.sin(mx * 0.025 - t * 0.15) * 8 + Math.cos(my * 0.02 + t * 0.4) * 6;
  const w2y = Math.cos(my * 0.022 + t * 0.18) * 8 + Math.sin(mx * 0.019 - t * 0.3) * 6;
  const sx = mx + w2x, sy = my + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [60+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65)*50, 0.11, 2.1, 1.05],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+1)*70, 0.085, 1.8, 0.85]
  ];
  let aS = 0, iS = 0, dS = 0;
  for (const [sX, sY, f, sp, wt] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * wt;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * wt;
    dS += Math.sin(d*f*0.3 - t*sp*0.4 + 0.7) * wt;
  }
  const n = src.length, act = aS/n, inh = iS/n, dif = dS/n;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = (Math.sin(sx*0.08-sy*0.06+t*1.5) + Math.cos(sx*0.06+sy*0.09-t*1.3))/2;
  const bg3 = Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg = bg1*0.5 + bg2*0.3 + bg3*0.2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const spiral2 = Math.sin(dist*0.08+ang*2-t*0.8)*Math.cos(dist*0.03-ang*5+t*1.1)*0.3;
  const spiral = spiral1 + spiral2;
  const cell1 = Math.sin(sx*0.15)*Math.sin(sy*0.15);
  const cell2 = Math.sin(sx*0.12+t*0.3)*Math.cos(sy*0.13-t*0.4);
  const cell = Math.tanh((cell1 + cell2*0.5 + Math.sin((sx+sy)*0.1+t)*0.3)*1.5)*0.3;
  const rd1 = act - inh*0.7 + bg*0.3 + spiral;
  const rd2 = rd1 + dif*0.4 + Math.sin(t*0.5)*0.1;
  const reaction = Math.tanh(rd2*2.2);
  const edge = 1.0 - Math.abs(reaction)**0.8 * 0.15;
  const glow = Math.max(0, Math.abs(reaction) - 0.5) * 0.4;
  const blend = reaction*0.7 + cell*0.2 + glow*0.1;
  const v = blend*0.5+0.5;
  const pal = [
    [6,12,48],[12,45,85],[18,95,115],[30,150,135],
    [120,185,120],[210,195,75],[220,140,80],[195,90,95],
    [130,50,75],[60,25,55],[6,12,48]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.85 + Math.sin(reaction*Math.PI)*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge)|0
  ];
}
